641	
642	    #[derive(Deserialize)]
643	    #[serde(rename_all = "camelCase")]
644	    struct WireDamage {
645	        item_type: String,
646	        amount: i64,
647	    }
648	
649	    #[derive(Deserialize)]
650	    struct WireIncident {
651	        damages: Vec<WireDamage>,
652	    }
653	
654	    #[derive(Deserialize)]
655	    #[serde(tag = "op", rename_all = "lowercase")]
656	    enum WireStep {
657	        Quote {
658	            items: Vec<WireItem>,
659	        },
660	        Claim {
661	            policy: usize,
662	            incident: WireIncident,
663	        },
664	    }
665	
666	    #[derive(Deserialize)]
667	    struct WireScenario {
668	        customer: WireCustomer,
669	        steps: Vec<WireStep>,
670	    }
671	
672	    #[derive(Serialize)]
673	    #[serde(untagged)]
674	    enum WireResult {
675	        Quote {
676	            premium: u64,
677	        },
678	        Claim {
679	            payout: u64,
680	            #[serde(rename = "remainingCap")]
681	            remaining_cap: u64,
682	        },
683	    }
684	
685	    #[derive(Serialize)]
686	    struct WireResults {
687	        results: Vec<WireResult>,
688	    }
