690	    /// A curse is recorded on an item only when the report states one.
691	    fn with_curse_recorded(item: Item, cursed: bool) -> Item {
692	        match cursed {
693	            true => item.cursed(),
694	            false => item,
695	        }
696	    }
697	
698	    impl WireItem {
699	        fn into_item(self) -> Result<Item, String> {
700	            let recorded = Item::new(ItemType::parse(&self.item_type)?)
701	                .with_enchantment(self.enchantment)
702	                .of_material(&self.material);
703	            Ok(with_curse_recorded(recorded, self.cursed))
704	        }
705	    }
706	
707	    impl WireDamage {
708	        fn into_damage(self) -> Result<Damage, String> {
709	            Ok(Damage::new(ItemType::parse(&self.item_type)?, self.amount))
710	        }
711	    }
712	
713	    impl WireStep {
714	        fn into_step(self) -> Result<Step, String> {
715	            match self {
716	                Self::Quote { items } => Ok(Step::Quote {
717	                    items: items
718	                        .into_iter()
719	                        .map(WireItem::into_item)
720	                        .collect::<Result<_, _>>()?,
721	                }),
722	                Self::Claim { policy, incident } => Ok(Step::Claim {
723	                    policy,
724	                    damages: incident
725	                        .damages
726	                        .into_iter()
727	                        .map(WireDamage::into_damage)
728	                        .collect::<Result<_, _>>()?,
729	                }),
730	            }
731	        }
732	    }
733	
734	    /// Reads a scenario as the MHPCO's documented input shape.
735	    pub fn read_scenario(document: &str) -> Result<Scenario, String> {
736	        let read: WireScenario = serde_json::from_str(document)
737	            .map_err(|failure| format!("the scenario could not be read: {failure}"))?;
738	        Ok(Scenario {
739	            customer: Customer::new(read.customer.years_with_mhpco),
740	            steps: read
741	                .steps
742	                .into_iter()
743	                .map(WireStep::into_step)
744	                .collect::<Result<_, _>>()?,
745	        })
746	    }
747	
748	    /// Writes handled steps as the MHPCO's documented output shape.
749	    pub fn write_results(results: Vec<StepResult>) -> Result<String, String> {
750	        let written = WireResults {
751	            results: results
752	                .into_iter()
753	                .map(|result| match result {
754	                    StepResult::Quote { premium } => WireResult::Quote { premium },
755	                    StepResult::Claim {
756	                        payout,
757	                        remaining_cap,
758	                    } => WireResult::Claim {
759	                        payout,
760	                        remaining_cap,
761	                    },
762	                })
763	                .collect(),
764	        };
765	        serde_json::to_string(&written)
766	            .map_err(|failure| format!("the results could not be written: {failure}"))
767	    }
768	}
