770	/// The MHPCO reads a scenario from the documented JSON, handles it, and writes
771	/// the results back in the documented JSON.
772	pub fn run_scenario_json(document: &str) -> Result<String, String> {
773	    let scenario = wire::read_scenario(document)?;
774	    wire::write_results(run_scenario(&scenario)?)
775	}
